final_src:
def shipping_cost(weight_kg, express=False):
    """Return the shipping cost in EUR for a parcel.

    The standard price is the base fee plus the per-kilogram charge; express
    delivery doubles that total.  The final amount is rounded to cents.
    """
    total = 4.00 + 1.75 * weight_kg
    if express:
        total *= 2
    return round(total, 2)

